// ============================================================
// SmartHire AI – Google Apps Script Sheet Writer  v2.0
// Deploy as Web App: Execute as "Me", Access: "Anyone"
// ============================================================
// COLUMN MAP (do NOT change order):
//  A = Timestamp        B = Company Name     C = Placement Cycle
//  D = Company + Cycle  E = Job Role         F = Seniority Level
//  G = Location         H = CTC              I = Eligibility
//  J = Core Skills      K = Tools/Tech       L = Complexity Score
//  M = Generated By     N = Target School
// ============================================================

// ── POST handler ─────────────────────────────────────────────
// Supports two actions:
//   1. _action:"clearSheet" → deletes all data rows, keeps header
//   2. (default)            → appends a new JD analysis row
function doPost(e) {
  try {
    const data  = JSON.parse(e.postData.contents);
    const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheets()[0];

    // ── Action: Clear all data rows ──────────────────────────
    if (data._action === "clearSheet") {
      var lastRow = sheet.getLastRow();
      var deleted = 0;
      if (lastRow > 1) {
        // Delete rows 2 → lastRow (keep row 1 = header)
        sheet.deleteRows(2, lastRow - 1);
        deleted = lastRow - 1;
      }
      return ContentService
        .createTextOutput(JSON.stringify({ cleared: true, rowsDeleted: deleted }))
        .setMimeType(ContentService.MimeType.JSON);
    }

    // ── Action: Append new JD row ─────────────────────────────
    // Auto-create header if sheet is empty
    if (sheet.getLastRow() === 0) {
      sheet.appendRow([
        "Timestamp", "Company Name", "Placement Cycle", "Company + Cycle",
        "Job Role", "Seniority Level", "Location", "CTC",
        "Eligibility", "Core Skills", "Tools & Technologies",
        "Complexity Score", "Generated By", "Target School"
      ]);
      var headerRange = sheet.getRange(1, 1, 1, 14);
      headerRange.setBackground("#1e293b");
      headerRange.setFontColor("#ffffff");
      headerRange.setFontWeight("bold");
      headerRange.setFontSize(11);
      sheet.setFrozenRows(1);
    }

    // IST Timestamp — prefer server-sent value, generate here as fallback
    var timestamp;
    if (data.analysis_timestamp_ist && data.analysis_timestamp_ist.trim() !== "") {
      timestamp = data.analysis_timestamp_ist.trim();
    } else {
      var now     = new Date();
      var istOff  = 5.5 * 60 * 60 * 1000;
      var ist     = new Date(now.getTime() + istOff + now.getTimezoneOffset() * 60 * 1000);
      var dd      = ("0" + ist.getDate()).slice(-2);
      var mm      = ("0" + (ist.getMonth() + 1)).slice(-2);
      var yyyy    = ist.getFullYear();
      var hh      = ("0" + ist.getHours()).slice(-2);
      var min     = ("0" + ist.getMinutes()).slice(-2);
      var ss      = ("0" + ist.getSeconds()).slice(-2);
      timestamp   = dd + "/" + mm + "/" + yyyy + " " + hh + ":" + min + ":" + ss;
    }

    var companyName   = data.company_name || "";
    var cycle         = data.campus_placement_year || "";
    var companyCycle  = companyName && cycle
                          ? companyName + " " + cycle
                          : companyName || cycle;
    var role          = data.job_role || data.role || "";
    var seniority     = data.seniority_level || "";
    var location      = data.job_location || data.location || "";
    var ctc           = data.ctc || "";
    var eligibility   = data.eligibility_criteria || "";
    var skills        = Array.isArray(data.core_skills)
                          ? data.core_skills.join(", ")
                          : (data.core_skills || "");
    var tools         = Array.isArray(data.tools_technologies)
                          ? data.tools_technologies.join(", ")
                          : (data.tools_technologies || "");
    var complexity    = data.complexity_score || "";
    var generatedBy   = data.generated_by || "SmartHire AI";

    // Only SOE or SOB allowed — remap anything else to SOE
    var rawSchool    = data.target_school || "";
    var targetSchool = (rawSchool.indexOf("SOB") !== -1 || rawSchool.indexOf("Business") !== -1)
                         ? "School of Business (SOB)"
                         : "School of Engineering (SOE)";

    sheet.appendRow([
      timestamp, companyName, cycle, companyCycle,
      role, seniority, location, ctc,
      eligibility, skills, tools, complexity,
      generatedBy, targetSchool
    ]);

    sheet.autoResizeColumns(1, 14);

    return ContentService
      .createTextOutput(JSON.stringify({ success: true, row: timestamp }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService
      .createTextOutput(JSON.stringify({ success: false, error: err.message }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}


// ── GET handler: Return all live sheet rows as JSON ───────────
// NOTE: Google's 302 redirect STRIPS query params, so we always
// return sheet data on ANY GET request — no ?action check needed.
function doGet(e) {
  try {
    var sheet     = SpreadsheetApp.getActiveSpreadsheet().getSheets()[0];
    var allValues = sheet.getDataRange().getValues();

    // Sheet is empty or only has a header row
    if (allValues.length <= 1) {
      return ContentService
        .createTextOutput(JSON.stringify({
          success : true,
          rows    : [],
          headers : allValues[0] || [],
          count   : 0
        }))
        .setMimeType(ContentService.MimeType.JSON);
    }

    var headers = allValues[0];
    var rows    = allValues.slice(1).map(function(row) {
      var obj = {};
      headers.forEach(function(h, i) {
        obj[h] = (row[i] !== undefined && row[i] !== null)
                   ? String(row[i]).trim()
                   : "";
      });
      return obj;
    });

    return ContentService
      .createTextOutput(JSON.stringify({
        success : true,
        rows    : rows,
        headers : headers,
        count   : rows.length
      }))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService
      .createTextOutput(JSON.stringify({ success: false, error: err.message }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}
